changeSet.sql:
create or alter procedure api.UpsertItemFields @userId int, @date datetime, @object varchar(25), @lookupPassedByValue bit as begin --create table #Items (ItemNumber int, IsValid bit, ObjectID int, AssetID bigint); --create table #Fields (ItemNumber int, FieldName nvarchar(250), FieldTypeID int, FieldValue nvarchar(max), LookupValue nvarchar(max));
-- Merge the field data. declare @fieldSql nvarchar(max) = ''; set @fieldSql = ' merge Field as t using ( select i.ObjectID, i.AssetID, f.*, case when coalesce(ft.Type,'''') = ''Link'' then 1 else 0 end IsValueUpdate from #Fields f inner join #Items i on i.ItemNumber = f.ItemNumber left Join FieldType Ft on Ft.ID = f.FieldTypeID ) as s '
if @object = 'Group' begin set @fieldSql = @fieldSql + 'on (t.AssetID = s.AssetID and t.FieldTypeID = s.FieldTypeID) ' end else if @object = 'Resource' begin set @fieldSql = @fieldSql + 'on (t.AssetID = s.AssetID and t.FieldTypeID = s.FieldTypeID) ' end else begin set @fieldSql = @fieldSql + 'on (t.ObjectType = @object and t.ObjectID = s.ObjectID and t.FieldTypeID = s.FieldTypeID) ' end set @fieldSql = @fieldSql + ' when matched then update set t.Value = case when s.IsValueUpdate = 1 and s.LookupValue is null then s.FieldValue else iif(s.LookupValue is null, null, s.LookupValue) end, t.FormattedValue = iif(s.LookupValue is null, s.FieldValue, null), t.UpdatedBy = @userId, t.UpdatedOn = @date when not matched by target then insert (AssetID, ObjectType, ObjectID, FieldTypeID, [Value], FormattedValue, UpdatedBy, UpdatedOn) values (s.AssetID, @object, s.ObjectID, s.FieldTypeID, case when s.IsValueUpdate = 1 and s.LookupValue is null then s.FieldValue else iif(s.LookupValue is null, null, s.LookupValue) end, iif(s.LookupValue is null, s.FieldValue, null), @userId, @date);'
exec sp_executesql @fieldSql, N'@userId int, @date datetime, @object varchar(50)', @userId, @date, @object;
if @object = 'Group' begin declare @groupassettypeid int = (select id from assettype where class = 12); if exists(select * from FieldType where AssetTypeID = @groupassettypeid and Type = 'Counter') begin insert into FieldCounterValue (AssetId, AssetTypeId, FieldTypeId, [Value]) select distinct i.AssetID, @groupassettypeid, ft.id, Null from #Items i cross apply (select fte.id from FieldType fte where fte.AssetTypeID = @groupassettypeid and fte.Type = 'Counter') ft left join dbo.FieldCounterValue FCV on FCV.AssetId = i.AssetID and FCV.FieldTypeId = ft.id where FCV.AssetId is null and i.AssetID is not null; end end
update F set F.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) from Field F inner join #Items i on i.AssetID = f.AssetId inner join #Fields t on t.ItemNumber = i.ItemNumber and t.FieldTypeID = F.FieldTypeID and F.[Value] is not null inner join FieldType FT on FT.ID = f.FieldTypeID and FT.Type = 'Lookup'; end
